.L177:
.L171:
; ---- ball.speedX = -ball.speedX
        mov     ax, [ball__speedX]
        neg     ax
        mov     [ball__speedX], ax
; ---- ball.player = pi
        mov     al, [hitPaddle__pi]
        mov     [ball__player], al          ; u8 -> u8, no widening
; ---- ball.color = paddleColor[ pi ]
        mov     al, [hitPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [ball__color], al           ; u8 -> u8, no widening
        ret

; ============================================== sub update ====

update:
; ---- if( isWinScreen ) return
        mov     al, [isWinScreen]
        test    al, al
        jz      .L183
        ret
.L183:
; ---- ball.x += ball.speedX
        mov     ax, [ball__x]
        mov     bx, [ball__speedX]
        add     ax, bx
        mov     [ball__x], ax
; ---- ball.y += ball.speedY
        mov     ax, [ball__y]
        mov     bx, [ball__speedY]
        add     ax, bx
        mov     [ball__y], ax
; ---- if( ball.y < 0 ){
        test    ax, ax
        jge     .L186                       ; signed <
; ---- ball.y = 0
        mov     word [ball__y], 0
; ---- ball.speedY = -ball.speedY
        mov     ax, [ball__speedY]
        neg     ax
        mov     [ball__speedY], ax
        jmp     .L187
.L186:
; ---- } else if( ball.y > ballYMax ){
        mov     ax, [ball__y]
        cmp     ax, 268
        jle     .L189                       ; signed >
; ---- ball.y = ballYMax
        mov     word [ball__y], 268
; ---- ball.speedY = -ball.speedY
        mov     ax, [ball__speedY]
        neg     ax
        mov     [ball__speedY], ax
.L189:
.L187:
; ---- if( ball.speedX > 0 && ball.x >= ballXMax ){
        mov     ax, [ball__speedX]
        test    ax, ax
        jle     .L192                       ; signed >
        mov     ax, [ball__x]
        cmp     ax, 296
        jl      .L192                       ; signed >=
; ---- hitPaddle( rightPlayer )
        mov     byte [hitPaddle__pi], 1
        call    hitPaddle
        jmp     .L193
.L192:
; ---- } else if ( ball.speedX < 0 && ball.x <= 0 ){
        mov     ax, [ball__speedX]
        test    ax, ax
        jge     .L196                       ; signed <
        mov     ax, [ball__x]
        test    ax, ax
        jg      .L196                       ; signed <=
; ---- hitPaddle( leftPlayer )
        mov     byte [hitPaddle__pi], 0
        call    hitPaddle
.L196:
.L193:
        ret

; ============================================== sub render ====

render:
; ---- if( isWinScreen ) return
        mov     al, [isWinScreen]
        test    al, al
        jz      .L200
        ret
.L200:
; ---- clearBall()
        call    clearBall
; ---- clearPaddle( leftPlayer )
        mov     byte [clearPaddle__pi], 0
        call    clearPaddle
; ---- clearPaddle( rightPlayer )
        mov     byte [clearPaddle__pi], 1
        call    clearPaddle
; ---- if ( ball.oldX >= netBallXMin && ball.oldX <= netBallXMax ) drawNet()
        mov     ax, [ball__oldX]
        cmp     ax, 144
        jl      .L203                       ; signed >=
        mov     ax, [ball__oldX]
        cmp     ax, 155
        jg      .L203                       ; signed <=
        call    drawNet
.L203:
; ---- drawBall()
        call    drawBall
; ---- drawPaddle( leftPlayer )
        mov     byte [drawPaddle__pi], 0
        call    drawPaddle
; ---- drawPaddle( rightPlayer )
        mov     byte [drawPaddle__pi], 1
        call    drawPaddle
; ---- player[ leftPlayer ].oldY = player[ leftPlayer ].y
        mov     ax, [player__y]
        mov     [player__oldY], ax
; ---- player[ rightPlayer ].oldY = player[ rightPlayer ].y
        mov     ax, [player__y + 2]
        mov     [player__oldY + 2], ax
; ---- ball.oldX = ball.x
        mov     ax, [ball__x]
        mov     [ball__oldX], ax
; ---- ball.oldY = ball.y
        mov     ax, [ball__y]
        mov     [ball__oldY], ax
        ret

; ============================================== sub waitRetrace ====

waitRetrace:
; ---- while ( inRetrace() ) pollKeyboard()
.L207:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L209
        call    pollKeyboard
.L208:
        jmp     .L207
.L209:
; ---- while ( !inRetrace() ) pollKeyboard()
.L211:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jnz     .L213
        call    pollKeyboard
.L212:
        jmp     .L211
.L213:
        ret

; ============================================== sub waitFrame ====

waitFrame:
; ---- waitRetrace()
        call    waitRetrace
; ---- waitRetrace()
        call    waitRetrace
        ret

; ============================================== sub tick ====

tick:
; ---- input()
        call    input
; ---- update()
        call    update
; ---- waitFrame()
        call    waitFrame
; ---- render()
        call    render
        ret

; ============================================== sub win ====

win:
; ---- isWinScreen = true
        mov     byte [isWinScreen], 1
; ---- waitFrame()
        call    waitFrame
; ---- drawBackground( winColor[ pi ] )
        mov     al, [win__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [winColor + bx]
        mov     [drawBackground__color], ax
        call    drawBackground
; ---- drawScore( leftPlayer )
        mov     byte [drawScore__pi], 0
        call    drawScore
; ---- drawScore( rightPlayer )
        mov     byte [drawScore__pi], 1
        call    drawScore
        ret

; ============================================== sub serve ====

serve:
; ---- ball.speedY = 0
        mov     word [ball__speedY], 0
; ---- volleyCount = 0
        mov     byte [volleyCount], 0
; ---- ball.x = serveX[ ball.player ]
        mov     al, [ball__player]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveX + bx]
        mov     [ball__x], ax
; ---- ball.y = player[ ball.player ].y + ballServeOffset
        mov     al, [ball__player]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        add     ax, 12
        mov     [ball__y], ax
; ---- ball.speedX = serveSpeedX[ ball.player ]
        mov     al, [ball__player]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveSpeedX + bx]
        mov     [ball__speedX], ax
; ---- ball.color = paddleColor[ ball.player ]
        mov     al, [ball__player]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [ball__color], al           ; u8 -> u8, no widening
        ret

; ============================================== sub start ====

start:
; ---- seedRandom( ticks() )
        call    ticks
        mov     ax, [ticks__ret]
        mov     [seedRandom__s], ax
        call    seedRandom
; ---- isWinScreen = false
        mov     byte [isWinScreen], 0
; ---- player[ leftPlayer ].speed = 0
        mov     byte [player__speed], 0
; ---- player[ leftPlayer ].score = 0
        mov     byte [player__score], 0
; ---- player[ leftPlayer ].y = paddleYHome
        mov     word [player__y], 122
; ---- player[ leftPlayer ].oldY = paddleYHome
        mov     word [player__oldY], 122
; ---- player[ rightPlayer ].speed = 0
        mov     byte [player__speed + 1], 0
; ---- player[ rightPlayer ].score = 0
        mov     byte [player__score + 1], 0
; ---- player[ rightPlayer ].y = paddleYHome
        mov     word [player__y + 2], 122
; ---- player[ rightPlayer ].oldY = paddleYHome
        mov     word [player__oldY + 2], 122
; ---- ball.player = randomBelow( len( player ) )
        mov     word [randomBelow__n], 2
        call    randomBelow
        mov     ax, [randomBelow__ret]
        mov     [ball__player], al          ; narrowed to u8
; ---- waitFrame()
        call    waitFrame
; ---- drawBackground( lightGreenW )
        mov     word [drawBackground__color], 257
        call    drawBackground
; ---- drawPlayfield()
        call    drawPlayfield
; ---- drawScore( leftPlayer )
        mov     byte [drawScore__pi], 0
        call    drawScore
; ---- drawScore( rightPlayer )
        mov     byte [drawScore__pi], 1
        call    drawScore
; ---- serve()
        call    serve
; ---- ball.oldX = ball.x
        mov     ax, [ball__x]
        mov     [ball__oldX], ax
; ---- ball.oldY = ball.y
        mov     ax, [ball__y]
        mov     [ball__oldY], ax
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

